from google.cloud import pubsub_v1
import json
from concurrent.futures import TimeoutError

def process_pub_sub_with_dead_letter(project_id, subscription_id, dead_letter_topic_id, timeout=10.0):
    subscriber = pubsub_v1.SubscriberClient()
    publisher = pubsub_v1.PublisherClient()
    subscription_path = subscriber.subscription_path(project_id, subscription_id)
    dead_letter_topic_path = publisher.topic_path(project_id, dead_letter_topic_id)

    def message_callback(message):
        try:
            payload = json.loads(message.data.decode("utf-8"))
            if payload.get("force_failure"):
                raise ValueError("Simulated processing failure")
            print(f"Successfully processed message {message.message_id}")
            message.ack()
        except Exception as e:
            print(f"Processing failed for {message.message_id}: {e}")
            try:
                dead_letter_future = publisher.publish(
                    dead_letter_topic_path,
                    data=message.data,
                    attributes={
                        **message.attributes,
                        "original_message_id": message.message_id,
                        "failure_reason": str(e)
                    }
                )
                dead_letter_future.result()
                print(f"Message {message.message_id} routed to dead-letter topic.")
                message.ack()
            except Exception as dlq_error:
                print(f"Dead-letter routing failed for {message.message_id}: {dlq_error}")
                message.nack()

    streaming_pull_future = subscriber.subscribe(subscription_path, callback=message_callback)
    try:
        streaming_pull_future.result(timeout=timeout)
    except TimeoutError:
        streaming_pull_future.cancel()
        streaming_pull_future.result()
